def count_interval_overlaps(intervals: list[tuple[int, int]]) -> int:
    # Sort intervals by their start times
    intervals.sort()

    # Initialize variables
    overlap_count = 0
    end = float('-inf')

    # Iterate through the sorted intervals
    for start, current_end in intervals:
        # If the current interval starts after the previous one ends, there's no overlap
        if start > end:
            end = current_end
        else:
            # Otherwise, there is an overlap
            overlap_count += 1
            # Update the end to the maximum end of the overlapping intervals
            end = max(end, current_end)

    return overlap_count
