def balanced_ternary_str(n: int) -> str:
    if n == 0:
        return "0"

    digits = []
    is_negative = n < 0
    n = abs(n)

    while n > 0:
        n, remainder = divmod(n, 3)
        if remainder == 2:
            digits.append('-')
            n += 1
        elif remainder == 1:
            digits.append('+')
        else:
            digits.append('0')

    if is_negative:
        digits.append('-')

    return ''.join(reversed(digits))
