def smallest_lcs(a: str, b: str) -> str:
    # Initialize a 2D array to store lengths of longest common suffixes
    m, n = len(a), len(b)
    lcsuff = [[0] * (n + 1) for _ in range(m + 1)]

    # Build the lcsuff array from bottom up
    for i in range(1, m + 1):
        for j in range(1, n + 1):
            if a[i - 1] == b[j - 1]:
                lcsuff[i][j] = lcsuff[i - 1][j - 1] + 1
            else:
                lcsuff[i][j] = 0

    # Find the maximum length of common suffix
    max_length = 0
    end_index_a = 0

    for i in range(1, m + 1):
        for j in range(1, n + 1):
            if lcsuff[i][j] > max_length:
                max_length = lcsuff[i][j]
                end_index_a = i

    # The smallest LCS is the common suffix of maximum length
    return a[end_index_a - max_length:end_index_a]
