import heapq
from typing import List, Tuple, Optional

def cheapest_route(edges: List[Tuple[str, str, int]], start: str, goal: str) -> Optional[Tuple[int, List[str]]]:
    if start == goal:
        return (0, [start])

    # Build the graph
    graph = {}
    for u, v, w in edges:
        if u not in graph:
            graph[u] = []
        if v not in graph:
            graph[v] = []
        graph[u].append((v, w))
        graph[v].append((u, w))

    # Priority queue for Dijkstra's algorithm
    pq = [(0, [start])]
    visited = set()

    while pq:
        cost, path = heapq.heappop(pq)
        current = path[-1]

        if current in visited:
            continue
        visited.add(current)

        if current == goal:
            return (cost, path)

        for neighbor, weight in graph.get(current, []):
            if neighbor not in visited:
                new_path = path + [neighbor]
                new_cost = cost + weight
                heapq.heappush(pq, (new_cost, new_path))

    return None
