from typing import List, Tuple, Optional

def cheapest_route(edges: List[Tuple[str, str, int]], start: str, goal: str) -> Optional[Tuple[int, List[str]]]:
    if start == goal:
        return (0, [start])

    # Build the graph
    graph = {}
    for u, v, w in edges:
        if u not in graph:
            graph[u] = []
        if v not in graph:
            graph[v] = []
        graph[u].append((v, w))
        graph[v].append((u, w))

    # Priority queue for Dijkstra's algorithm
    pq = [(0, start, [start])]
    visited = set()

    while pq:
        cost, node, path = heapq.heappop(pq)

        if node in visited:
            continue
        visited.add(node)

        if node == goal:
            return (cost, path)

        for neighbor, weight in graph[node]:
            if neighbor not in visited:
                new_path = path + [neighbor]
                heapq.heappush(pq, (cost + weight, neighbor, new_path))

    return None
```

