from typing import List, Tuple, Optional
from collections import defaultdict, deque

def cheapest_route(edges: List[Tuple[str, str, int]], start: str, goal: str) -> Optional[Tuple[int, List[str]]]:
    if start == goal:
        return (0, [start])

    graph = defaultdict(list)
    for u, v, w in edges:
        graph[u].append((v, w))
        graph[v].append((u, w))

    min_cost = float('inf')
    best_path = None

    def bfs():
        nonlocal min_cost, best_path
        queue = deque([(start, 0, [start])])
        visited = set()

        while queue:
            current, cost, path = queue.popleft()

            if cost > min_cost:
                continue

            if current == goal:
                if cost < min_cost or (cost == min_cost and path < best_path):
                    min_cost = cost
                    best_path = path
                continue

            for neighbor, weight in graph[current]:
                if (current, neighbor) not in visited:
                    visited.add((current, neighbor))
                    queue.append((neighbor, cost + weight, path + [neighbor]))

    bfs()

    return (min_cost, best_path) if best_path else None
