def cheapest_route(edges: list[tuple[str, str, int]], start: str, goal: str) -> tuple[int, list[str]] | None:
    graph = {}
    for u, v, cost in edges:
        if u not in graph:
            graph[u] = {}
        if v not in graph:
            graph[v] = {}
        graph[u][v] = cost
        graph[v][u] = cost  # Assuming undirected graph

    priority_queue = [(0, start, [start])]
    visited = set()

    while priority_queue:
        current_cost, current_node, path = heapq.heappop(priority_queue)

        if current_node in visited:
            continue

        if current_node == goal:
            return current_cost, path

        visited.add(current_node)

        for neighbor, cost in graph[current_node].items():
            if neighbor not in visited:
                heapq.heappush(priority_queue, (current_cost + cost, neighbor, path + [neighbor]))

    return None
