def lex_topological_order(n: int, pairs: List[Tuple[int, int]]) -> List[int]:
    if n == 0:
        return []

    # Create adjacency list and in-degree array
    adj_list = [[] for _ in range(n)]
    in_degree = [0] * n

    for a, b in pairs:
        if a == b:
            return []  # Cycle detected
        adj_list[a].append(b)
        in_degree[b] += 1

    # Initialize the queue with nodes having zero in-degree
    queue = []
    for i in range(n):
        if in_degree[i] == 0:
            queue.append(i)

    # Perform topological sort
    result = []
    while queue:
        # Sort the queue to get lexicographically smallest order
        queue.sort()
        node = queue.pop(0)
        result.append(node)

        for neighbor in adj_list[node]:
            in_degree[neighbor] -= 1
            if in_degree[neighbor] == 0:
                queue.append(neighbor)

    # Check if all nodes are included in the result
    if len(result) != n:
        return []  # Cycle detected

    return result

