        count = 0
        for neighbor in graph[node]:
            if not visited[neighbor]:
                visited[neighbor] = True
                count += dfs(neighbor, current_length + 1, target, graph, visited, shortest_path_length)
                visited[neighbor] = False

        return count

    visited = [False] * n
    visited[source] = True
    return dfs(source, 0, target, graph, visited, shortest_path_length)
