def evaluate_expression(expr: str) -> int:
    import re
    import operator
    from collections import deque

    # Tokenize the expression
    tokens = re.findall(r'\d+|\+|-|\*|/|\^|\(|\)', expr.replace(' ', ''))

    # Operator precedence and associativity
    precedence = {'^': 4, '*': 3, '/': 3, '+': 2, '-': 2}
    right_associative = {'^'}

    # Shunting Yard algorithm to convert to postfix
    def shunting_yard(tokens):
        output = []
        operators = deque()
        for token in tokens:
            if token.isdigit():
                output.append(int(token))
            elif token == '(':
                operators.append(token)
            elif token == ')':
                while operators and operators[-1] != '(':
                    output.append(operators.pop())
                operators.pop()  # Remove '('
            else:  # Operator
                while (operators and operators[-1] != '(' and
                       (precedence[operators[-1]] > precedence[token] or
                        (precedence[operators[-1]] == precedence[token] and token not in right_associative))):
                    output.append(operators.pop())
                operators.append(token)
        while operators:
            output.append(operators.pop())
        return output

    # Evaluate postfix expression
    def evaluate_postfix(postfix):
        stack = []
        ops = {'+': operator.add, '-': operator.sub, '*': operator.mul, '/': operator.floordiv, '^': operator.pow}
        for token in postfix:
            if isinstance(token, int):
                stack.append(token)
            else:
                b = stack.pop()
                a = stack.pop()
                if token == '/' and b == 0:
                    raise ZeroDivisionError("division by zero")
                result = ops[token](a, b)
                stack.append(result)
        return stack[0]

    postfix = shunting_yard(tokens)
    return evaluate_postfix(postfix)
