import operator
import re

def evaluate_expression(expr: str) -> int:
    # Define operator precedence and functions
    ops = {
        '+': operator.add,
        '-': operator.sub,
        '*': operator.mul,
        '/': lambda x, y: x // y if y != 0 else ZeroDivisionError,
        '^': operator.pow,
    }

    # Tokenize the expression
    tokens = re.findall(r'\d+|\+|\-|\*|\/|\^|\(|\)', expr.replace(' ', ''))

    # Convert tokens to postfix notation (Shunting Yard algorithm)
    output = []
    operators = []

    for token in tokens:
        if token.isdigit():
            output.append(int(token))
        elif token == '(':
            operators.append(token)
        elif token == ')':
            while operators and operators[-1] != '(':
                output.append(operators.pop())
            operators.pop()  # Remove '('
        else:
            while (operators and operators[-1] != '(' and
                   (token == '^' or
                    (operators[-1] in ('*', '/', '+', '-') and
                     token in ('+', '-')))):
                output.append(operators.pop())
            operators.append(token)

    while operators:
        output.append(operators.pop())

    # Evaluate the postfix expression
    stack = []

    for token in output:
        if isinstance(token, int):
            stack.append(token)
        else:
            if token == '-':
                # Unary minus
                if isinstance(stack[-1], int):
                    stack[-1] = -stack[-1]
                else:
                    stack.append(-stack.pop())
            else:
                b = stack.pop()
                a = stack.pop()
                result = ops[token](a, b)
                if isinstance(result, ZeroDivisionError):
                    raise ZeroDivisionError("Division by zero")
                stack.append(result)

    return stack[0]
