import re

def tokenize_code(source: str) -> list[tuple[str, str]]:
    tokens = []
    i = 0
    while i < len(source):
        if source[i].isspace():
            i += 1
        elif source[i].isdigit():
            match = re.match(r'\d+(\.\d+)?', source[i:])
            if match:
                tokens.append(('NUMBER', match.group(0)))
                i += match.end()
            else:
                raise ValueError(f"Invalid character at position {i}")
        elif re.match(r'[a-zA-Z_]', source[i]):
            match = re.match(r'[a-zA-Z_]\w*', source[i:])
            if match:
                tokens.append(('NAME', match.group(0)))
                i += match.end()
            else:
                raise ValueError(f"Invalid character at position {i}")
        elif re.match(r'[+\-*/<>=(),]', source[i]):
            tokens.append(('OP', source[i]))
            i += 1
        elif re.match(r'==|!=|<=|>=', source[i:i+2]):
            tokens.append(('OP', source[i:i+2]))
            i += 2
        else:
            raise ValueError(f"Invalid character at position {i}")
    return tokens
