import re

def tokenize_code(source: str) -> list[tuple[str, str]]:
    tokens = []
    i = 0
    n = len(source)

    while i < n:
        char = source[i]

        if char.isspace():
            i += 1
            continue

        if char.isdigit():
            match = re.match(r'\d+(\.\d+)?', source[i:])
            if match:
                tokens.append(('NUMBER', match.group(0)))
                i += match.end()
                continue
            else:
                raise ValueError(f"Invalid character at position {i}: {char}")

        if char.isalpha() or char == '_':
            match = re.match(r'[a-zA-Z_][a-zA-Z0-9_]*', source[i:])
            if match:
                tokens.append(('NAME', match.group(0)))
                i += match.end()
                continue
            else:
                raise ValueError(f"Invalid character at position {i}: {char}")

        if char in '+-*/<>()=':
            tokens.append(('OP', char))
            i += 1
            continue

        if char == '.':
            if i + 1 < n and source[i + 1].isdigit():
                match = re.match(r'\.\d+', source[i:])
                if match:
                    tokens.append(('NUMBER', match.group(0)))
                    i += match.end()
                    continue
            raise ValueError(f"Invalid character at position {i}: {char}")

        if i + 1 < n and source[i:i+2] in ('==', '!=', '<=', '>='):
            tokens.append(('OP', source[i:i+2]))
            i += 2
            continue

        raise ValueError(f"Invalid character at position {i}: {char}")

    return tokens
