from math import gcd
from functools import reduce

def lcm(a: int, b: int) -> int:
    return abs(a * b) // gcd(a, b)

def solve_congruences(congruences: list[tuple[int, int]]) -> tuple[int, int] | None:
    if not congruences:
        return (0, 1)

    x, L = 0, 1
    for r, m in congruences:
        if L % m == 0:
            if x % m != r % m:
                return None
            continue

        # Find the smallest positive solution for the current congruence
        r = r % m
        for i in range(m):
            if (x + i * L) % m == r:
                x += i * L
                break
        else:
            return None

        # Update L to the least common multiple of the current L and m
        L = lcm(L, m)

    # Reduce x to the range [0, L)
    x %= L
