def format_table(rows: list[list[str]], aligns: str) -> str:
    if not rows:
        return ""

    num_columns = len(rows[0])
    column_widths = [max(len(cell) for cell in column) for column in zip(*rows)]

    formatted_rows = []
    for row in rows:
        formatted_cells = []
        for i, cell in enumerate(row):
            width = column_widths[i]
            align = aligns[i]
            if align == 'l':
                formatted_cell = cell.ljust(width)
            elif align == 'r':
                formatted_cell = cell.rjust(width)
            elif align == 'c':
                formatted_cell = cell.center(width)
            formatted_cells.append(formatted_cell)
        formatted_rows.append(" | ".join(formatted_cells))

    return "\n".join(formatted_rows)
