def format_table(rows: list[list[str]], aligns: str) -> str:
    if not rows:
        return ""

    # Calculate the maximum width for each column
    column_widths = [max(len(cell) for cell in column) for column in zip(*rows)]

    def pad_cell(cell: str, width: int, align: str) -> str:
        padding = width - len(cell)
        if align == 'l':
            return cell + ' ' * padding
        elif align == 'r':
            return ' ' * padding + cell
        elif align == 'c':
            left_padding = padding // 2
            right_padding = padding - left_padding
            return ' ' * left_padding + cell + ' ' * right_padding
        return cell

    formatted_rows = []
    for row in rows:
        formatted_cells = [
            pad_cell(cell, width, align)
            for cell, width, align in zip(row, column_widths, aligns)
        ]
        formatted_rows.append(" | ".join(formatted_cells))

    return "\n".join(formatted_rows)
