def rotate_rings(matrix: list[list[int]], k: int) -> list[list[int]]:
    if not matrix or not matrix[0]:
        return []

    n = len(matrix)
    result = [row[:] for row in matrix]

    def rotate_ring(r, c, size, k):
        k = k % (2 * size - 2)
        if k < 0:
            k += 2 * size - 2

        # Top row
        for i in range(size - 1):
            result[r][c + i] = matrix[r][c + (i - k) % (size - 1)]

        # Right column
        for i in range(size - 1):
            result[r + i][c + size - 1] = matrix[r + (i - k) % (size - 1)][c + size - 1]

        # Bottom row
        for i in range(size - 1):
            result[r + size - 1][c + size - 1 - i] = matrix[r + size - 1][c + size - 1 - (i - k) % (size - 1)]

        # Left column
        for i in range(size - 1):
            result[r + size - 1 - i][c] = matrix[r + size - 1 - (i - k) % (size - 1)][c]

    layer = 0
    while 2 * layer < n:
        rotate_ring(layer, layer, n - 2 * layer, k)
        layer += 1

    return result
