def min_slides(grid: list[str]) -> int:
    rows = len(grid)
    cols = len(grid[0]) if rows > 0 else 0
    if rows == 0 or cols == 0:
        return 0

    # Find the topmost '1' in each column
    topmost_ones = [float('inf')] * cols
    for r in range(rows):
        for c in range(cols):
            if grid[r][c] == '1':
                topmost_ones[c] = min(topmost_ones[c], r)

    # Calculate the minimum slides needed
    min_slides = 0
    for c in range(cols):
        min_slides = max(min_slides, topmost_ones[c] + 1)

    return min_slides
