def expand_template(template: str, values: dict[str, str]) -> str:
    def replace_placeholder(match):
        key = match.group(1)
        return values.get(key, match.group(0))

    # Regular expression to find placeholders
    pattern = re.compile(r'\{([^{}]*)\}')

    # Replace placeholders with corresponding values from the dictionary
    result = pattern.sub(replace_placeholder, template)

    return result

