import re

def identifier_to_snake(name: str) -> str:
    # Split the name by underscores and hyphens
    pieces = re.split(r'[_-]', name)

    # Further split pieces by transitions between lower/upper case, letter/digit, digit/letter
    words = []
    for piece in pieces:
        words.extend(re.findall(r'[a-z]+|[A-Z][a-z]*|[A-Z]+(?=[A-Z][a-z])|[0-9]+|[a-zA-Z][0-9]|[0-9][a-zA-Z]', piece))

    # Join the words with underscores and convert to lower case
    return '_'.join(words).lower()

import re

def identifier_to_snake(name: str) -> str:
    # Split the name by underscores and hyphens
    parts = re.split(r'[_-]+', name)

    # Initialize an empty list to hold the snake_case parts
    snake_parts = []

    for part in parts:
        # If the part is empty, skip it
        if not part:
            continue

        # Convert the part to snake_case
        snake_part = ''
        for i, char in enumerate(part):
            if i > 0 and char.isupper() and part[i-1].islower():
                snake_part += '_'
            snake_part += char.lower()

        # Add the converted part to the list
        snake_parts.append(snake_part)

    # Join the parts with underscores and return the result
    return '_'.join(snake_parts)

import re

def identifier_to_snake(name: str) -> str:
    # Replace camelCase to snake_case
    s1 = re.sub('(.)([A-Z][a-z]+)', r'\1_\2', name)
    # Replace remaining uppercase letters with underscore and lowercase
    return re.sub('([a-z0-9])([A-Z])', r'\1_\2', s1).lower()

