def free_slots(busy: list[tuple[int, int]], day_start: int, day_end: int, min_len: int) -> list[tuple[int, int]]:
    if day_start >= day_end:
        return []

    # Filter out empty busy ranges and sort by start time
    busy = sorted((s, e) for s, e in busy if s < e)

    free_slots = []
    current_start = day_start

    for s, e in busy:
        if s > current_start and s - current_start >= min_len:
            free_slots.append((current_start, s))
        current_start = max(current_start, e)

    if current_start <= day_end - min_len:
        free_slots.append((current_start, day_end))

    return free_slots
