            table[away]['points'] += 3
            table[away]['goal_difference'] += away_goals - home_goals
            table[home]['goal_difference'] -= away_goals - home_goals
        else:
            table[home]['points'] += 1
            table[away]['points'] += 1

    return sorted(
        [(team, data['points'], data['goal_difference'], data['goals_scored'])
         for team, data in table.items()],
        key=lambda x: (-x[1], -x[2], -x[3], x[0])
    )
