from itertools import permutations

def seating_arrangements(guests: list[str], conflicts: list[tuple[str, str]]) -> list[list[str]]:
    if not guests:
        return [[]]

    conflicts_set = set(conflicts)

    def is_valid(arrangement):
        for i in range(len(arrangement) - 1):
            if (arrangement[i], arrangement[i + 1]) in conflicts_set or (arrangement[i + 1], arrangement[i]) in conflicts_set:
                return False
        return True

    all_permutations = permutations(guests)
    valid_arrangements = [list(p) for p in all_permutations if is_valid(p)]

    return sorted(valid_arrangements)
