def process_orders(events: list[tuple[str, str, int]]) -> tuple[dict[str, int], list[tuple[str, int]]]:
    stock = {}
    waiting = []

    for kind, item, quantity in events:
        if kind == 'receive':
            if item in stock:
                stock[item] += quantity
            else:
                stock[item] = quantity

            # Process waiting orders for this item
            i = 0
            while i < len(waiting):
                waiting_item, waiting_quantity = waiting[i]
                if waiting_item == item and stock[item] >= waiting_quantity:
                    stock[item] -= waiting_quantity
                    waiting.pop(i)
                else:
                    i += 1

        elif kind == 'order':
            if item in stock and stock[item] >= quantity:
                stock[item] -= quantity
            else:
                waiting.append((item, quantity))

    # Filter out items with stock 0
    stock = {item: quantity for item, quantity in stock.items() if quantity > 0}

    return stock, waiting
