def process_orders(events: list[tuple[str, str, int]]) -> tuple[dict[str, int], list[tuple[str, int]]]:
    stock = {}
    waiting = []
    order_queue = {}

    for kind, item, quantity in events:
        if item not in stock:
            stock[item] = 0
            order_queue[item] = []

        if kind == 'receive':
            stock[item] += quantity
            while order_queue[item] and stock[item] >= order_queue[item][0][1]:
                _, order_quantity = order_queue[item].pop(0)
                stock[item] -= order_quantity
        elif kind == 'order':
            if stock[item] >= quantity:
                stock[item] -= quantity
            else:
                order_queue[item].append((item, quantity))

    waiting = [order for item_orders in order_queue.values() for order in item_orders]
    return stock, waiting
