        action, product, quantity = event
        if action == 'add':
            if product in inventory:
                inventory[product] += quantity
            else:
                inventory[product] = quantity
        elif action == 'sell':
            if product in inventory and inventory[product] >= quantity:
                inventory[product] -= quantity
                order_history.append((product, quantity))
