def run_stack_program(program: list[str]) -> list[int] | None:
    stack = []
    ip = 0
    executed_instructions = 0

    while ip < len(program) and executed_instructions < 1000:
        instruction = program[ip]
        parts = instruction.split()
        op = parts[0]

        if op == "PUSH":
            if len(parts) != 2:
                return None
            try:
                n = int(parts[1])
                stack.append(n)
            except ValueError:
                return None
        elif op == "POP":
            if len(stack) < 1:
                return None
            stack.pop()
        elif op == "DUP":
            if len(stack) < 1:
                return None
            stack.append(stack[-1])
        elif op == "SWAP":
            if len(stack) < 2:
                return None
            stack[-1], stack[-2] = stack[-2], stack[-1]
        elif op in ("ADD", "SUB", "MUL"):
            if len(stack) < 2:
                return None
            b = stack.pop()
            a = stack.pop()
            if op == "ADD":
                stack.append(a + b)
            elif op == "SUB":
                stack.append(a - b)
            elif op == "MUL":
                stack.append(a * b)
        elif op == "JMP":
            if len(parts) != 2:
                return None
            try:
                t = int(parts[1])
                if t < 0:
                    return None
                ip = t
                continue
            except ValueError:
                return None
        elif op == "JZ":
            if len(stack) < 1:
                return None
            if stack.pop() == 0:
                if len(parts) != 2:
                    return None
                try:
                    t = int(parts[1])
                    if t < 0:
                        return None
                    ip = t
                    continue
                except ValueError:
                    return None
        else:
            return None

        ip += 1
        executed_instructions += 1

    if executed_instructions >= 1000:
        return None

    return stack
