def convert_base(number: str, from_base: int, to_base: int) -> str:
    if not number or number == '-' or any(c.lower() not in '0123456789abcdefghijklmnopqrstuvwxyz'[:from_base] for c in number.replace('-', '')):
        raise ValueError("Invalid input")

    # Handle negative numbers
    negative = number.startswith('-')
    number = number.lstrip('-')

    # Convert from from_base to base 10
    base_10_value = 0
    for char in number:
        base_10_value = base_10_value * from_base + '0123456789abcdefghijklmnopqrstuvwxyz'.index(char.lower())

    # Handle zero case
    if base_10_value == 0:
        return '0'

    # Convert from base 10 to to_base
    digits = []
    while base_10_value:
        digits.append('0123456789abcdefghijklmnopqrstuvwxyz'[base_10_value % to_base])
        base_10_value //= to_base

    # Handle negative sign
    if negative:
        digits.append('-')

    # Return the result in the correct order
    return ''.join(reversed(digits))

