from collections import deque

def shortest_path_one_break(grid: list[str]) -> int:
    rows, cols = len(grid), len(grid[0])
    directions = [(0, 1), (1, 0), (0, -1), (-1, 0)]

    # Find the start and end positions
    start = None
    end = None
    for r in range(rows):
        for c in range(cols):
            if grid[r][c] == 'S':
                start = (r, c)
            elif grid[r][c] == 'E':
                end = (r, c)

    # BFS to find the shortest path with at most one wall break
    queue = deque([(start, 0, False)])  # (current position, moves, wall broken)
    visited = set()
    visited.add((start, False))

    while queue:
        (r, c), moves, wall_broken = queue.popleft()

        if (r, c) == end:
            return moves

        for dr, dc in directions:
            nr, nc = r + dr, c + dc
            if 0 <= nr < rows and 0 <= nc < cols:
                if grid[nr][nc] == '.':
                    if (nr, nc, wall_broken) not in visited:
                        visited.add((nr, nc, wall_broken))
                        queue.append(((nr, nc), moves + 1, wall_broken))
                elif grid[nr][nc] == '#' and not wall_broken:
                    if (nr, nc, True) not in visited:
                        visited.add((nr, nc, True))
                        queue.append(((nr, nc), moves + 1, True))

    return -1
