    rows, cols = len(grid), len(grid[0])
    directions = [(0, 1), (1, 0), (0, -1), (-1, 0)]

    # Find the positions of S and E
    start = None
    end = None
    for r in range(rows):
        for c in range(cols):
            if grid[r][c] == 'S':
                start = (r, c)
            elif grid[r][c] == 'E':
                end = (r, c)

    # BFS with a queue of (row, col, steps, has_broken_wall)
    queue = deque([(start[0], start[1], 0, False)])
    visited = set()
    visited.add((start[0], start[1], False))

    while queue:
        r, c, steps, has_broken_wall = queue.popleft()

        if (r, c) == end:
            return steps

        for dr, dc in directions:
            nr, nc = r + dr, c + dc
            if 0 <= nr < rows and 0 <= nc < cols:
                if grid[nr][nc] == '.':
                    if (nr, nc, has_broken_wall) not in visited:
                        visited.add((nr, nc, has_broken_wall))
                        queue.append((nr, nc, steps + 1, has_broken_wall))
                elif grid[nr][nc] == '#' and not has_broken_wall:
                    if (nr, nc, True) not in visited:
                        visited.add((nr, nc, True))
                        queue.append((nr, nc, steps + 1, True))

    return -1

