    if not grid:
        return []

    rows, cols = len(grid), len(grid[0])
    new_grid = [[grid[r][c] for c in range(cols)] for r in range(rows)]

    def is_unstable(r, c):
        return new_grid[r][c] >= 4

    def topple(r, c):
        new_grid[r][c] -= 4
        for dr, dc in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
            nr, nc = r + dr, c + dc
            if 0 <= nr < rows and 0 <= nc < cols:
                new_grid[nr][nc] += 1

    while True:
        unstable = False
        for r in range(rows):
            for c in range(cols):
                if is_unstable(r, c):
                    unstable = True
                    topple(r, c)
        if not unstable:
            break

    return new_grid

