def parse_config(text: str) -> dict:
    config = {}
    lines = text.split('\n')
    for line in lines:
        line = line.strip()
        if line and not line.startswith('#'):
            match = re.match(r'(\w+)\s*=\s*(.+)', line)
            if match:
                key, value = match.groups()
                config[key] = value
    return config
