import zlib
import pickle

def restore_cache_entry(blob: bytes) -> dict:
    try:
        # Decompress the blob
        decompressed_blob = zlib.decompress(blob)

        # Unpickle the decompressed blob
        entry = pickle.loads(decompressed_blob)

        # Validate the entry to ensure it is a dictionary
        if not isinstance(entry, dict):
            raise ValueError("Decompressed data is not a dictionary")

        # Validate keys and values in the dictionary
        for key, value in entry.items():
            if not isinstance(key, str):
                raise ValueError("Dictionary key is not a string")
            if not isinstance(value, (str, int, float, list, dict)):
                raise ValueError("Dictionary value is not a valid type")

        return entry
    except (zlib.error, pickle.UnpicklingError, ValueError) as e:
        raise ValueError("Invalid cache entry blob") from e
