        jobs = yaml.safe_load(text)
        if not isinstance(jobs, list):
            raise ValueError("The YAML content is not a list of jobs.")

        parsed_jobs = []
        for job in jobs:
            if not isinstance(job, dict) or 'name' not in job or 'interval' not in job:
                raise ValueError("Each job must be a dictionary with 'name' and 'interval' keys.")

            name = job['name']
            interval = job['interval']
            enabled = job.get('enabled', True)

            if not isinstance(name, str) or not isinstance(interval, int) or not isinstance(enabled, bool):
                raise ValueError("Invalid types for job attributes.")

            parsed_jobs.append({'name': name, 'interval': interval, 'enabled': enabled})

        return parsed_jobs

    except yaml.YAMLError as e:
        raise ValueError("Error parsing YAML content.") from e
    except Exception as e:
        raise ValueError("Invalid job definition.") from e

