import math
from typing import Callable

def evaluate_formula(formula: str, x: float) -> float:
    # Define the allowed functions
    functions: dict[str, Callable[[float], float]] = {
        'sqrt': math.sqrt,
        'abs': abs,
        'sin': math.sin,
        'cos': math.cos
    }

    # Replace x with the value in the formula
    formula = formula.replace('x', str(x))

    # Add spaces around operators and functions for easier parsing
    for op in ['+', '-', '*', '/', '**']:
        formula = formula.replace(op, f' {op} ')
    for func in functions:
        formula = formula.replace(func, f' {func}(')

    # Split the formula into tokens
    tokens = formula.split()

    # Evaluate the formula using a stack-based approach
    stack = []
    i = 0
    while i < len(tokens):
        token = tokens[i]
        if token.isnumeric() or (token[0] == '-' and token[1:].isnumeric()):
            stack.append(float(token))
        elif token in functions:
            if i + 1 >= len(tokens) or tokens[i + 1] != '(':
                raise ValueError("Invalid formula")
            # Find the matching closing parenthesis
            open_count = 1
            j = i + 2
            while j < len(tokens) and open_count > 0:
                if tokens[j] == '(':
                    open_count += 1
                elif tokens[j] == ')':
                    open_count -= 1
                j += 1
            if j >= len(tokens):
                raise ValueError("Invalid formula")
            # Evaluate the expression inside the parentheses
            sub_expr = ' '.join(tokens[i + 2:j])
            sub_value = evaluate_formula(sub_expr, x)
            stack.append(functions[token](sub_value))
            i = j - 1
        elif token in ['+', '-', '*', '/', '**']:
            if len(stack) < 2:
                raise ValueError("Invalid formula")
            b = stack.pop()
            a = stack.pop()
            if token == '+':
                stack.append(a + b)
            elif token == '-':
                stack.append(a - b)
            elif token == '*':
                stack.append(a * b)
            elif token == '/':
                if b == 0:
                    raise ZeroDivisionError("Division by zero")
                stack.append(a / b)
            elif token == '**':
                stack.append(a ** b)
        else:
            raise ValueError("Invalid formula")
        i += 1

    if len(stack) != 1:
        raise ValueError("Invalid formula")

    return stack[0]
