import math
from typing import Callable

def evaluate_formula(formula: str, x: float) -> float:
    # Define allowed functions
    allowed_functions = {
        'sqrt': math.sqrt,
        'abs': abs,
        'sin': math.sin,
        'cos': math.cos
    }

    # Define a safe eval function
    def safe_eval(expr: str, x: float) -> float:
        # Create a local scope with allowed functions and the variable x
        local_scope = {**allowed_functions, 'x': x}
        try:
            # Evaluate the expression safely
            result = eval(expr, {"__builtins__": None}, local_scope)
            return result
        except ZeroDivisionError:
            raise ZeroDivisionError("Division by zero")
        except Exception as e:
            raise ValueError(f"Invalid formula: {e}")

    # Check if the formula contains only allowed characters and functions
    allowed_chars = "x0123456789+-*/()., "
    if not all(char in allowed_chars for char in formula):
        raise ValueError("Invalid formula")

    # Check for invalid function calls
    for func in allowed_functions:
        if formula.count(func) != formula.count(f"{func}("):
            raise ValueError("Invalid formula")

    # Evaluate the formula
    return safe_eval(formula, x)
