    if target.startswith('/') and (len(target) == 1 or target[1] != '/'):
        return True

    # Check for absolute URL with matching host
    parsed_url = urlparse(target)
    if parsed_url.scheme in ('http', 'https'):
        return parsed_url.hostname.lower() == host.lower()

    return False
