import re

def is_allowed_webhook(url: str) -> bool:
    # Check if the URL starts with https:// (case insensitive)
    if not re.match(r'^https://', url, re.IGNORECASE):
        return False

    # Check for backslashes, spaces, or control characters
    if re.search(r'[\\ \x00-\x1f\x7f]', url):
        return False

    # Parse the URL to extract the host and port
    try:
        from urllib.parse import urlparse
        parsed_url = urlparse(url)
        host = parsed_url.hostname
        port = parsed_url.port
    except ValueError:
        return False

    # Check if the port is absent or 443
    if port is not None and port != 443:
        return False

    # Check if the host is a valid DNS name
    if not host:
        return False

    # Remove one '.' at the very end if present
    if host.endswith('.'):
        host = host[:-1]

    # Split the host into labels
    labels = host.split('.')

    # Check if the host has two or more labels
    if len(labels) < 2:
        return False

    # Check each label
    for label in labels:
        if not label or not re.match(r'^[a-zA-Z0-9-]+$', label):
            return False

    # Check if the last label consists only of letters
    if not re.match(r'^[a-zA-Z]+$', labels[-1]):
        return False

    # Check if the host is not localhost or ends with .localhost (case insensitive)
    if host.lower() == 'localhost' or host.lower().endswith('.localhost'):
        return False

    return True
