def is_allowed_webhook(url: str) -> bool:
    # Check if the URL starts with https:// (case insensitive)
    if not re.match(r'^https://', url, re.IGNORECASE):
        return False

    # Check for invalid characters
    if re.search(r'[\\ \x00-\x1f\x7f]', url):
        return False

    # Parse the URL
    parsed_url = re.match(r'^https://(?:(?:[^\@]+@)?[^\@:]+(?::[^\@]+)?@)?([^:/]+)(?::(\d+))?(?:/.*)?$', url, re.IGNORECASE)
    if not parsed_url:
        return False

    host = parsed_url.group(1)
    port = parsed_url.group(2)

    # Remove one trailing dot if present
    if host.endswith('.'):
        host = host[:-1]

    # Check if the host is a valid DNS name
    dns_labels = host.split('.')
    if len(dns_labels) < 2:
        return False
    for label in dns_labels[:-1]:
        if not re.match(r'^[a-zA-Z0-9-]+$', label):
            return False
    if not re.match(r'^[a-zA-Z]+$', dns_labels[-1]):
        return False

    # Check if the host is not localhost or ends with .localhost
    if host.lower() == 'localhost' or host.lower().endswith('.localhost'):
        return False

    # Check if the port is absent or 443
    if port and port != '443':
        return False

    return True
