def fetch_target_allowed(url: str, allowed_hosts: list[str]) -> bool:
    parsed_url = urlparse(url)

    # Check if the scheme is http or https
    if parsed_url.scheme.lower() not in ['http', 'https']:
        return False

    # Check if there is user info in the URL
    if parsed_url.username or parsed_url.password:
        return False

    # Extract the host and remove any port
    host = parsed_url.hostname.lower()
    if ':' in host:
        host = host.split(':')[0]

    # Remove trailing dot if present
    if host.endswith('.'):
        host = host[:-1]

    # Check if the host is in the allowed hosts list
    allowed_hosts_lower = [h.lower() for h in allowed_hosts]
    if host in allowed_hosts_lower:
        return False

    # Check for sub-domain match
    for allowed_host in allowed_hosts_lower:
        if allowed_host.endswith('.') and host.endswith(allowed_host):
            return False

