def call_api(url: str, api_token: str, http_get) -> dict:
    headers = {
        'Authorization': f'Bearer {api_token}',
        'Content-Type': 'application/json'
    }
    response = http_get(url, headers=headers)
    response.raise_for_status()
    return response.json()

import logging

def call_api(url: str, api_token: str, http_get) -> dict:
    logging.info(f"Calling API at {url}")
    try:
        address = f"{url}?api_token={api_token}"
        response = http_get(address)
        return response
    except Exception as e:
        logging.error(f"Failed to call API at {url}")
        raise e

